package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamChemReactBank2 {
  private const val T = "මවුලය, රසායනික ප්‍රතික්‍රියා, අම්ල-භෂ්ම හා විද්‍යුත් රසායනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "රසායනික ගණනය, අම්ල-භෂ්ම හා විද්‍යුත් රසායනයට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("කාබන් (C = 12) ග්‍රෑම් 24 ක අඩංගු කාබන් පරමාණු මවුල සංඛ්‍යාව කීයද?", "2 mol", "1 mol", "0.5 mol", "12 mol", "n = 24 / 12 = 2 mol."),
    q("මැග්නීසියම් ක්ලෝරයිඩ් (MgCl₂) මවුල 1 ක අඩංගු ක්ලෝරයිඩ් අයන (Cl⁻) මවුල ගණන කීයද?", "2 mol", "1 mol", "3 mol", "0.5 mol", "MgCl₂ 1 mol විඝටනයෙන් Mg²⁺ 1 mol හා Cl⁻ 2 mol ලැබේ."),
    q("ඇමෝනියම් නයිට්‍රේට් (NH₄NO₃, M = 80 g mol⁻¹) ග්‍රෑම් 40 ක අඩංගු මවුල සංඛ්‍යාව කීයද?", "0.5 mol", "1.0 mol", "2.0 mol", "0.25 mol", "n = 40 / 80 = 0.5 mol."),
    q("කැල්සියම් ඔක්සයිඩ් (CaO, M = 56 g mol⁻¹) මවුල 0.25 ක ස්කන්ධය කොපමණද?", "14 g", "28 g", "56 g", "7 g", "m = 0.25 × 56 = 14 g."),
    q("ජලය (H₂O) ග්‍රෑම් 9 ක අඩංගු හයිඩ්‍රජන් පරමාණු මවුල ගණන කීයද? (H = 1, O = 16)", "1.0 mol", "0.5 mol", "2.0 mol", "9.0 mol", "ජලය 9 g යනු H₂O 0.5 mol කි; එහි H පරමාණු 0.5 × 2 = 1.0 mol ඇත."),
    q("සල්ෆර් ඩයොක්සයිඩ් (SO₂) අණුවේ සාපේක්ෂ අණුක ස්කන්ධය කීයද? (S = 32, O = 16)", "64", "48", "32", "80", "32 + (16 × 2) = 64."),
    q("යකඩ (Fe = 56) ග්‍රෑම් 112 ක් සහ සල්ෆර් (S = 32) ග්‍රෑම් 64 ක් සම්පූර්ණයෙන් ප්‍රතික්‍රියා කර සෑදෙන FeS ස්කන්ධය කීයද?", "176 g", "88 g", "112 g", "64 g", "Fe + S → FeS; 2 mol Fe (112 g) + 2 mol S (64 g) → 2 mol FeS (176 g)."),
    q("4Fe + 3O₂ → 2Fe₂O₃ සමීකරණය අනුව ෆෙරික් ඔක්සයිඩ් මවුල 1 ක් සෑදීමට ප්‍රතික්‍රියා කළ යුතු යකඩ මවුල ගණන කීයද?", "2 mol", "4 mol", "1 mol", "3 mol", "Fe : Fe₂O₃ අනුපාතය 4 : 2 හෙවත් 2 : 1 වේ."),
    q("වීදුරු පාත්‍රයක තබා ඇති CaCO₃ සහ HCl අතර ප්‍රතික්‍රියාවේ සීඝ්‍රතාව පරීක්ෂණාත්මකව මැනිය හැකි පහසුම ක්‍රමයක් කුමක්ද?", "පිටවන CO₂ වායු පරිමාව හෝ ස්කන්ධ අඩු වීම මැනීම", "වීදුරු පාත්‍රයේ ඇති ද්‍රාවණයේ වර්ණය මැනීම", "පාත්‍රයේ ඇති ද්‍රාවණ කඳේ මුළු උස මැනීම", "භාවිත කළ අම්ල ද්‍රාවණයේ තාපාංකය මැනීම", "CO₂ පිටවීම නිසා පද්ධතියේ මුළු ස්කන්ධය ක්‍රමයෙන් අඩු වේ."),
    q("හයිඩ්‍රජන් පෙරොක්සයිඩ් (2H₂O₂ → 2H₂O + O₂) වියෝජනය වීමේ ප්‍රතික්‍රියාව ක්ෂණිකව වේගවත් කරන අකාබනික උත්ප්‍රේරකය කුමක්ද?", "මැන්ගනීස් ඩයොක්සයිඩ් (MnO₂)", "සෝඩියම් ක්ලෝරයිඩ්", "වැලි", "සීනි", "අමු අර්තාපල් කැබැල්ලක ඇති කැටලේස් එන්සයිමය ද ජෛව උත්ප්‍රේරකයක් ලෙස ක්‍රියා කරයි."),
    q("සාමාන්‍යයෙන් රසායනික ප්‍රතික්‍රියාවක උෂ්ණත්වය 10°C කින් ඉහළ දැමූ විට ප්‍රතික්‍රියා සීඝ්‍රතාවට සිදුවන්නේ කුමක්ද?", "සීඝ්‍රතාව ආසන්න වශයෙන් දෙගුණ වේ", "සීඝ්‍රතාව අඩකින් අඩු වේ", "ප්‍රතික්‍රියාව නවතී", "කිසිදු වෙනසක් නොවේ", "උෂ්ණත්වය වැඩි වත්ම සක්‍රීයන ශක්තිය ඉක්මවන අණු ප්‍රමාණය විශාල ලෙස ඉහළ යයි."),
    q("ආහාර ශීතකරණයේ තැබීමෙන් නරක් වීම ප්‍රමාද වන්නේ ප්‍රතික්‍රියා සීඝ්‍රතාවට බලපාන කුමන සාධකය අඩු කිරීමෙන්ද?", "උෂ්ණත්වය", "පෘෂ්ඨ වර්ගඵලය", "ආලෝකය", "සාන්ද්‍රණය", "අඩු උෂ්ණත්වයේදී ආහාර නරක් කරන රසායනික හා ක්ෂුද්‍රජීවී ප්‍රතික්‍රියා මන්දගාමී වේ."),
    q("පිටි මෝලක හෝ ගල් අඟුරු පතලක ඉතා සියුම් දූවිලි පුපුරා යාමේ අවදානමක් පවතින්නේ කුමක් නිසාද?", "පෘෂ්ඨ වර්ගඵලය අතිශයින් වැඩි වී දහන වේගය අධික වීම", "සියුම් දූවිලි වාතයේ ඇති ජල වාෂ්ප සමඟ ද්‍රව සෑදීම", "පතල අභ්‍යන්තරයේ උෂ්ණත්වය 0°C දක්වා පහත වැටීම", "පද්ධතිය තුළ දහනයට අවශ්‍ය ඔක්සිජන් නොමැති වීම", "කුඩා අංශුවල ඉහළ පෘෂ්ඨ වර්ගඵලය නිසා ක්ෂණික දහනයක් ඇති වේ."),
    q("තාප අවශෝෂක ප්‍රතික්‍රියාවක (Endothermic) ශක්ති මට්ටම් සටහනේදී ප්‍රතික්‍රියකවල ශක්තියට සාපේක්ෂව ඵලවල ශක්තිය කෙබඳුද?", "ඵලවල ශක්තිය ප්‍රතික්‍රියකවලට වඩා වැඩිය", "ඵලවල ශක්තිය ප්‍රතික්‍රියකවලට වඩා අඩුය", "ඵල හා ප්‍රතික්‍රියක ශක්තීන් දෙකම සමාන වේ", "ප්‍රතික්‍රියා අවසානයේ ඵල ශක්තිය ශුන්‍ය වේ", "පරිසරයෙන් ශක්තිය උරා ගෙන ඉහළ ශක්ති මට්ටමකට ඵල ගමන් කරයි."),
    q("ප්‍රභාසංස්ලේෂණය හා ජලය විද්‍යුත් විච්ඡේදනය යන දෙකම ශක්ති විපර්යාස අනුව කුමන ගණයට අයත්ද?", "තාප/ශක්ති අවශෝෂක ක්‍රියාවලි", "තාපදායක දහන", "ස්වයංසිද්ධ උදාසීනීකරණ", "මලකඩ කෑම්", "දෙකේදීම බාහිරින් ශක්තිය (සූර්යාලෝකය / විදුලිය) සැපයිය යුතුය."),
    q("ප්‍රබල අම්ලයක් සහ ප්‍රබල භෂ්මයක් උදාසීන වීමේදී (උදා: HCl + NaOH) නිදහස් වන මවුලික උදාසීනීකරණ තාපය සැමවිටම නියත අගයක් (-57 kJ mol⁻¹ පමණ) ගන්නේ ඇයි?", "සිදුවන්නේ H⁺ හා OH⁻ එක්වී H₂O සෑදීම පමණක් බැවින්", "සියලුම ප්‍රබල අම්ල හා භෂ්ම එකම මවුලික ස්කන්ධ දරන බැවින්", "සෑදෙන සියලුම ලවණ ජලයේ අද්‍රාව්‍ය අවක්ෂේප වන බැවින්", "උදාසීනීකරණයේදී පරිසරයෙන් තාපය අවශෝෂණය වන බැවින්", "Na⁺ හා Cl⁻ ප්‍රේක්ෂක අයන (Spectator ions) ලෙස පවතී."),
    q("සාන්ද්‍ර හා තනුක අම්ල අතර වෙනස නිවැරදිව පැහැදිලි කරන්නේ කුමක්ද?", "සාන්ද්‍ර අම්ලයේ ඒකක පරිමාවක අම්ල මවුල ගණන වැඩිය", "සියලුම සාන්ද්‍ර අම්ල සැමවිටම දුබල අම්ල ගණයට වැටේ", "තනුක අම්ල ද්‍රාවණයක කිසිදු H⁺ අයනයක් අඩංගු නොවේ", "සාන්ද්‍ර අම්ල රසායනිකව ප්‍රබල භෂ්ම ලෙස ක්‍රියා කරයි", "ප්‍රබල බව යනු අයනීකරණ ප්‍රමාණයයි; සාන්ද්‍ර බව යනු ද්‍රාව්‍ය ප්‍රමාණයයි."),
    q("කිසියම් ද්‍රාවණයක pH අගය 1 සිට 14 දක්වා වූ පරිමාණයේ 'ප්‍රබල ක්ෂාරයකට' (උදා: NaOH) ගැළපෙන pH අගය කුමක්ද?", "13 – 14", "1 – 2", "5 – 6", "7", "pH = 7 උදාසීන වන අතර 14 ආසන්නය ප්‍රබලම භාෂ්මික අවස්ථාවයි."),
    q("වීදුරු පාත්‍රයක ඇති ඇසිටික් අම්ලය (දුබල අම්ලය) සඳහා ගැළපෙන pH අගය කුමක්ද?", "3 – 5 පමණ", "14", "0 – 1", "11", "සමාන සාන්ද්‍රණයේදී ප්‍රබල අම්ල (pH ≈ 1) තරම් H⁺ අයන සාන්ද්‍රණයක් දුබල අම්ලවල නැත."),
    q("ස්වාභාවික ජලය, වැසි ජලය හා දෙහි යුෂ pH අගය අඩු වන පිළිවෙළට (වැඩි සිට අඩු දක්වා) පෙළගැස්වූ විට නිවැරදි පිළිවෙළ කුමක්ද?", "පිරිසිදු ජලය (7) > සාමාන්‍ය වැසි ජලය (5.6) > දෙහි යුෂ (2.4)", "දෙහි යුෂ > වැසි ජලය > පිරිසිදු ජලය", "වැසි ජලය > පිරිසිදු ජලය > දෙහි යුෂ", "පිරිසිදු ජලය > දෙහි යුෂ > වැසි ජලය", "වාතයේ CO₂ දියවීම නිසා සාමාන්‍ය වැසි ජලය ද මඳක් ආම්ලික (pH ≈ 5.6) වේ."),
    q("මීමැස්සෙකු දෂ්ට කළ විට ඇතිවන ආම්ලික විෂ (ෆෝමික් අම්ලය) උදාසීන කිරීමට ආලේප කළ හැකි හොඳම ගෘහස්ථ ද්‍රව්‍යය කුමක්ද?", "බේකිං සෝඩා (NaHCO₃) ද්‍රාවණයක්", "විනාකිරි", "දෙහි යුෂ", "ලුණු කුඩු", "බේකිං සෝඩා මෘදු භෂ්මයක් බැවින් සමට හානි නොකර අම්ලය උදාසීන කරයි."),
    q("දෙබරෙකු (Wasp) දෂ්ට කළ විට එහි විෂ භාෂ්මික බැවින් වේදනාව අඩු කිරීමට ආලේප කළ හැක්කේ කුමක්ද?", "විනාකිරි හෝ දෙහි යුෂ", "තනුක බේකිං සෝඩා ද්‍රාවණය", "තෙත් කළ අළු හුණු ස්වල්පයක්", "සාමාන්‍ය රෙදි සෝදන සබන්", "මෘදු කාබනික අම්ලයක් භාෂ්මික විෂ උදාසීන කරයි."),
    q("රසායනාගාරයේදී ක්ෂාරීය ද්‍රාවණයක් අම්ලයක් සමඟ අනුමාපනය කරන විට හරියටම උදාසීන ලක්ෂ්‍යය හඳුනා ගැනීමට දමන ද්‍රව්‍යය කුමක්ද?", "දර්ශකයක් (Indicator)", "උත්ප්‍රේරකයක්", "අවක්ෂේපයක්", "විජලකාරකයක්", "ෆීනෝල්ෆ්තැලීන් හෝ මෙතිල් ඔරේන්ජ් අන්ත ලක්ෂ්‍යයේදී වර්ණය වෙනස් කරයි."),
    q("ලෝහ ඔක්සයිඩ හා ලෝහ හයිඩ්‍රොක්සයිඩ බොහෝ විට කුමන ගුණ පෙන්වයිද?", "භාෂ්මික ගුණ (Bases)", "ආම්ලික ගුණ", "විකිරණශීලී ගුණ", "හැලජන ගුණ", "ජලයේ දියවන භෂ්ම 'ක්ෂාර' (Alkalis) ලෙස හැඳින්වේ (උදා: NaOH, KOH, Ca(OH)₂)."),
    q("පහත දැක්වෙන භෂ්ම අතුරින් ජලයේ දිය නොවන (ක්ෂාරයක් නොවන) භෂ්මය කුමක්ද?", "කොපර්(II) ඔක්සයිඩ් (CuO)", "සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH)", "පොටෑසියම් හයිඩ්‍රොක්සයිඩ් (KOH)", "ඇමෝනියා ද්‍රාවණය (NH₄OH)", "CuO ජලයේ අද්‍රාව්‍ය වුවද අම්ල සමඟ ප්‍රතික්‍රියා කර ලවණ හා ජලය සාදන බැවින් භෂ්මයකි."),
    q("පෙරහන් කඩදාසි මගින් NaOH කැට වාතයට විවෘතව තැබූ විට තෙත් වී ද්‍රවයක් බවට පත් වන්නේ කුමන ගුණය නිසාද?", "ජල වාෂ්ප අවශෝෂණය කරන ද්‍රාව්‍යතා ගුණය", "ඝන අවස්ථාවේ සිට ඍජුව වායු වන ඌර්ධ්වපාතනය", "මතුපිට ද්‍රව අණු වායු බවට පත් වන වාෂ්පීභවනය", "ඉලෙක්ට්‍රෝන ලබා ගන්නා රසායනික ඔක්සිහරණය", "NaOH හා අණුක CaCl₂ වාතයේ තෙතමනය උරාගෙන එහි දියවේ."),
    q("ලෝහ කැබලි කිහිපයක් (Cu, Fe, Mg, Zn) තනුක HCl වලට වෙන වෙනම දැමූ විට වේගවත්ම බුබුළු නැඟීම දැකිය හැක්කේ කුමන ලෝහයෙන්ද?", "මැග්නීසියම් (Mg)", "සින්ක් (Zn)", "යකඩ (Fe)", "තඹ (Cu)", "සක්‍රියතා ශ්‍රේණියේ ඉහළම පිහිටි ලෝහය Mg බැවිනි."),
    q("ZnO + C → Zn + CO ප්‍රතික්‍රියාවේදී කාබන් (C) ක්‍රියා කර ඇත්තේ කුමක් ලෙසද?", "ඔක්සිහාරකය (Reducing agent) ලෙස", "ඔක්සිකාරකය ලෙස", "උත්ප්‍රේරකය ලෙස", "අම්ලයක් ලෙස", "කාබන් ZnO වලින් ඔක්සිජන් ඉවත් කර තමා CO බවට ඔක්සිකරණය වී ඇත."),
    q("Fe³⁺ අයනයක් ඉලෙක්ට්‍රෝනයක් ලබා ගෙන Fe²⁺ අයනයක් බවට පත් වීම කුමන ප්‍රතික්‍රියාවක්ද?", "ඔක්සිහරණය (Reduction)", "ඔක්සිකරණය", "උදාසීනීකරණය", "වියෝජනය", "ඉලෙක්ට්‍රෝන ලබා ගැනීම ඔක්සිහරණය වේ."),
    q("ලෝහ විඛාදනය හෙවත් යකඩ මලකඩ කෑම වේගවත් කරන සාධක දෙක මොනවාද?", "ලුණු (විද්‍යුත් විච්ඡේද්‍ය) සහ අම්ල පැවතීම", "තීන්ත සහ ග්‍රීස්", "සින්ක් ආලේපනය සහ වියළි වාතය", "නයිට්‍රජන් සහ ආගන්", "මුහුදුබඩ ප්‍රදේශවල ලුණු මිශ්‍ර වාතය නිසා යකඩ ඉක්මනින් මලකඩ කයි."),
    q("පොටෑසියම් ක්ලෝරයිඩ්, සින්ක් සහ කොපර් සල්ෆේට් භාවිතයෙන් සාදන කෝෂයක විද්‍යුත් ගාමක බලය රඳා පවතින්නේ කුමක් මතද?", "ලෝහ දෙක සක්‍රියතා ශ්‍රේණියේ දුරස්ථභාවය මත", "භාවිත කළ බීකරයේ හරස්කඩ පළල මත", "සම්බන්ධක කම්බියේ පිටත ආවරණ වර්ණය මත", "ද්‍රාවණය අඩංගු බීකරයේ මුළු බර මත", "ලෝහ දෙක අතර සක්‍රියතා වෙනස වැඩි වන තරමට ලැබෙන වෝල්ටීයතාව වැඩි වේ."),
    q("Mg සහ Cu ඉලෙක්ට්‍රෝඩවලින් සෑදූ සරල කෝෂයකත්, Zn සහ Cu ඉලෙක්ට්‍රෝඩවලින් සෑදූ කෝෂයකත් අතරින් වැඩි වෝල්ටීයතාවක් දෙන්නේ කවරක්ද?", "Mg සහ Cu කෝෂය", "Zn සහ Cu කෝෂය", "දෙකම සමාන වේ", "දෙකම ශුන්‍ය වේ", "සක්‍රියතා ශ්‍රේණියේ Mg, Cu ට වඩා බොහෝ ඉහළින් පිහිටයි."),
    q("විද්‍යුත් රසායනික කෝෂයක බාහිර පරිපථය දිගේ ඉලෙක්ට්‍රෝන ගලා යන දිශාව කුමක්ද?", "වැඩි සක්‍රීය සෘණ අග්‍රයේ සිට අඩු සක්‍රීය ධන අග්‍රයට", "ධන කැතෝඩ අග්‍රයේ සිට සෘණ ඇනෝඩ අග්‍රය දෙසට", "විද්‍යුත් විච්ඡේද්‍ය ද්‍රාවණය හරහා පමණක් ගලයි", "කිසිදු ඉලෙක්ට්‍රෝන ප්‍රවාහයක් බාහිරව ගමන් නොකරයි", "සම්මත විද්‍යුත් ධාරාව ධන අග්‍රයේ සිට සෘණ අග්‍රය දෙසට ද ඉලෙක්ට්‍රෝන එහි ප්‍රතිවිරුද්ධ දිශාවට ද ගලයි."),
    q("සෝඩියම් ක්ලෝරයිඩ් ඝන හා ප්ලාස්ටික් අතරින් විද්‍යුත් විච්ඡේදනය කළ හැකි වන්නේ කවරක්ද?", "ද්‍රවීකරණය කළ හෝ ජලයේ දිය කළ NaCl", "වියළි ඝන NaCl", "ඝන ප්ලාස්ටික්", "ආස්‍රැත ජලය", "විද්‍යුත් විච්ඡේදනයට චලනය විය හැකි අයන අත්‍යවශ්‍ය වේ."),
    q("නිකල් හෝ රිදී විද්‍යුත් ආලේපනය කිරීමේදී ඇනෝඩය ලෙස භාවිත කළ යුත්තේ කුමක්ද?", "පිරිසිදු නිකල් හෝ රිදී තහඩුව", "ආලේප කළ යුතු යකඩ හැන්ද", "ප්ලාස්ටික් දණ්ඩක්", "වීදුරු කූරක්", "ඇනෝඩය ක්ෂය වෙමින් ද්‍රාවණයේ ලෝහ අයන සාන්ද්‍රණය නියතව තබා ගනී."),
    q("විලීන ලෙඩ් බ්‍රෝමයිඩ් (PbBr₂) ග්‍රැෆයිට් ඉලෙක්ට්‍රෝඩ අතර විද්‍යුත් විච්ඡේදනය කළ විට ඇනෝඩයේදී පිටවන රතු-දුඹුරු වාෂ්පය කුමක්ද?", "බ්‍රෝමීන් වාෂ්ප (Br₂)", "ලෙඩ් ලෝහය", "හයිඩ්‍රජන්", "ඔක්සිජන්", "Br⁻ අයන ඇනෝඩයේදී ඉලෙක්ට්‍රෝන පිට කර Br₂ බවට ඔක්සිකරණය වේ; කැතෝඩයේදී ඊයම් ලැබේ."),
    q("ජලීය කොපර්(II) සල්ෆේට් ද්‍රාවණයක් 'කාබන් (නිෂ්ක්‍රීය)' ඉලෙක්ට්‍රෝඩ යොදා විද්‍යුත් විච්ඡේදනය කළ විට ඇනෝඩයේදී පිටවන වායුව කුමක්ද?", "ඔක්සිජන් (O₂)", "හයිඩ්‍රජන් (H₂)", "සල්ෆර් ඩයොක්සයිඩ්", "තඹ", "SO₄²⁻ ට වඩා ජලයේ OH⁻ පහසුවෙන් ඔක්සිකරණය වී O₂ පිට කරයි; ද්‍රාවණයේ නිල් පැහැය ක්‍රමයෙන් මැකී යයි."),
    q("හයිඩ්‍රජන් පෙරොක්සයිඩ් H₂O₂ හා භාවිතයේදී MnO₂ කුඩා ප්‍රමාණයක් එකතු කළ විට සිදුවන ප්‍රතික්‍රියාව කුමක්ද?", "MnO₂ ඉතිරි වෙමින් වේගයෙන් O₂ වායුව පිට වීම", "MnO₂ සම්පූර්ණයෙන් දිය වීම", "H₂ වායුව පිට වීම", "ද්‍රාවණය මිදී යාම", "MnO₂ ධන උත්ප්‍රේරකයක් ලෙස ක්‍රියා කරයි."),
    q("සෝඩියම් බයිකාබනේට් (NaHCO₃) හා හයිඩ්‍රොක්ලෝරික් අම්ලය ප්‍රතික්‍රියා කළ විට නිපදවෙන වායුව හා ලවණය මොනවාද?", "CO₂ වායුව සහ NaCl ලවණය", "H₂ වායුව සහ NaCl", "O₂ වායුව සහ NaOH", "Cl₂ වායුව සහ Na₂CO₃", "NaHCO₃ + HCl → NaCl + H₂O + CO₂."),
    q("පොටෑසියම් හයිඩ්‍රොක්සයිඩ් (KOH) සහ නයිට්‍රික් අම්ලය (HNO₃) ප්‍රතික්‍රියා කිරීමෙන් සෑදෙන ලවණය කුමක්ද?", "පොටෑසියම් නයිට්‍රේට් (KNO₃)", "පොටෑසියම් නයිට්‍රයිඩ්", "පොටෑසියම් සල්ෆේට්", "නයිට්‍රස් ඔක්සයිඩ්", "KOH + HNO₃ → KNO₃ + H₂O."),
    q("සින්ක් කැබැල්ලක් පිරිසිදු කැල්සියම් ක්ලෝරයිඩ් (CaCl₂) ද්‍රාවණයකට දැමූ විට සිදු වන්නේ කුමක්ද?", "කිසිදු ප්‍රතික්‍රියාවක් සිදු නොවේ", "කැල්සියම් තැන්පත් වේ", "හයිඩ්‍රජන් පිටවේ", "සින්ක් පුපුරා යයි", "Zn සක්‍රියතාව Ca ට වඩා අඩු බැවින් Ca විස්ථාපනය කළ නොහැක."),
    q("සාමාන්‍යයෙන් අම්ල හා භෂ්ම පරීක්ෂාවේදී භාවිත කරන 'සාර්වත්‍ර දර්ශකය' (Universal indicator) මඟින් ලබාගත හැකි විශේෂ වාසිය කුමක්ද?", "ද්‍රාවණයේ දළ pH අගය හා ප්‍රබලතාව හඳුනා ගත හැකි වීම", "එය අම්ල උදාසීන කිරීම", "එය ද්‍රාවණ රත් කිරීම", "එය සෑම විටම නිල් පැහැ වීම", "වර්ණ වෙනස pH වර්ණ තීරුව සමඟ සසඳා pH 1–14 අතර අගය සොයයි."),
    q("ඇලුමිනියම් තහඩුවක් වාතයේ තැබූ විට එය යකඩ මෙන් දිගටම මලකඩ නොකා ආරක්ෂිතව පවතින්නේ ඇයි?", "තුනී Al₂O₃ ඔක්සයිඩ් ස්තරයක් සෑදී ආරක්ෂා වීම", "ඇලුමිනියම් රසායනිකව ඉතා නිෂ්ක්‍රීය ලෝහයක් වීම", "ඇලුමිනියම් ඔක්සිජන් සමඟ ප්‍රතික්‍රියා නොකිරීම", "ඇලුමිනියම් වාතයේ තෙතමනයට දියවී යාම", "මෙම ස්වයං-ආරක්ෂක ඔක්සයිඩ් පටලය 'ඇනෝඩීකරණය' මඟින් තවත් ඝන කළ හැක."),
    q("2Mg + O₂ → 2MgO යන ප්‍රතික්‍රියාවේදී ඔක්සිකරණය වන හා ඔක්සිහරණය වන ද්‍රව්‍ය පිළිවෙළින් මොනවාද?", "Mg ඔක්සිකරණය වේ; O₂ ඔක්සිහරණය වේ", "O₂ ඔක්සිකරණය වේ; Mg ඔක්සිහරණය වේ", "MgO ඔක්සිකරණය වේ", "ප්‍රතික්‍රියාව රෙඩොක්ස් නොවේ", "Mg ඉලෙක්ට්‍රෝන පිට කර Mg²⁺ වන අතර O₂ ඉලෙක්ට්‍රෝන ගෙන O²⁻ වේ."),
    q("තඹ (Cu) කම්බියක් වාතයේ රත් කළ විට එහි මතුපිට කළු පැහැති කුඩක් සෑදෙන්නේ කුමක් නිසාද?", "කොපර්(II) ඔක්සයිඩ් (CuO) සෑදීම", "කොපර් කාබනේට් සෑදීම", "තඹ වාෂ්ප වීම", "සල්ෆර් තැන්පත් වීම", "2Cu + O₂ → 2CuO (කළු පැහැති ඝනයකි)."),
    q("හයිඩ්‍රජන් පෙරොක්සයිඩ් (H₂O₂) කළු හෝ දුඹුරු පැහැති වීදුරු බෝතල්වල ගබඩා කරන්නේ ඇයි?", "ආලෝකය නිසා ජලය හා ඔක්සිජන් බවට වියෝජනය වැළැක්වීමට", "ආලෝකය නොමැති විට එය පහසුවෙන් ඝන බවට පත්වන නිසා", "වීදුරු බෝතලයේ පෙනුම ආකර්ෂණීය කර ගැනීමට", "වාතයේ ඇති ඔක්සිජන් වායුව වැඩිපුර අවශෝෂණයට", "UV හා දෘශ්‍ය ආලෝකය H₂O₂ වියෝජනය වේගවත් කරයි."),
    q("පොටෑසියම් පර්මැංගනේට් (KMnO₄) රත් කළ විට පිටවන වායුව හඳුනා ගත හැක්කේ කෙසේද?", "පුලිඟු කූරක් නැවත දල්වා ගැනීමෙන් (ඔක්සිජන් වායුව)", "හුනු දියර කිරි පැහැ වීමෙන්", "පොප් හඬක් නැගීමෙන්", "තෙත් ලිට්මස් නිල් වීමෙන්", "2KMnO₄ → K₂MnO₄ + MnO₂ + O₂."),
    q("එතනොයික් අම්ලය 50 cm³ ක් හා සමාන සාන්ද්‍රණයේ NaOH 50 cm³ ක් මිශ්‍ර කළ විට සිදු වන ප්‍රතික්‍රියාව කුමක්ද?", "සෝඩියම් එතනොඒට් (ලවණය) හා ජලය සෑදීම", "මීතේන් වායුව පිට වීම", "කිසිදු ප්‍රතික්‍රියාවක් නොවීම", "හයිඩ්‍රජන් පිටවීම", "CH₃COOH + NaOH → CH₃COONa + H₂O."),
    q("ආස්‍රැත ජලයේ (pH = 7) H⁺ සහ OH⁻ අයන සාන්ද්‍රණ අතර සම්බන්ධතාව කුමක්ද?", "H⁺ සහ OH⁻ අයන සාන්ද්‍රණ සමාන වේ", "H⁺ ඉතා වැඩිය", "OH⁻ ඉතා වැඩිය", "H⁺ හෝ OH⁻ කිසිවක් නැත", "25°C දී දෙකෙහිම සාන්ද්‍රණය 10⁻⁷ mol dm⁻³ වේ."),
    q("රසායනික ප්‍රතික්‍රියාවක 'ප්‍රත්‍යාවර්ත ප්‍රතික්‍රියාවක්' (Reversible reaction) යනු කුමක්ද?", "ඵල නැවත ප්‍රතික්‍රියා කර ප්‍රතික්‍රියක බවට හැරිය හැකි ප්‍රතික්‍රියාව", "කිසිවිටෙක ආපසු හැරවිය නොහැකි ප්‍රතික්‍රියාව", "එක් දිශාවකට පමණක් යන දහනය", "පුපුරා යන ප්‍රතික්‍රියාව", "N₂ + 3H₂ ⇌ 2NH₃ යනු සම්භාව්‍ය ප්‍රත්‍යාවර්ත ප්‍රතික්‍රියාවකි."),
    q("ඇමෝනියා නිෂ්පාදන හේබර් ක්‍රමයේදී අමුද්‍රව්‍ය වන නයිට්‍රජන් සහ හයිඩ්‍රජන් ලබා ගන්නේ පිළිවෙළින් කවර මූලාශ්‍රවලින්ද?", "වායුගෝලීය වාතයෙන් සහ ස්වාභාවික වායුවෙන් (මීතේන්)", "සාගර ජලයෙන් සහ ගල් අඟුරුවලින්", "හුණුගල් සහ වැලිවලින්", "සල්ෆර් සහ යකඩවලින්", "වාතයේ භාගික ආසවනයෙන් N₂ ද මීතේන් හා හුමාල ප්‍රතික්‍රියාවෙන් H₂ ද ලබා ගනී."),
    q("කිසියම් ද්‍රාවණයක OH⁻ අයන නිසා රතු ලිට්මස් නිල් වේ. HCl වායුව වියළි බෙන්සීන් වල දිය කළහොත් නිල් ලිට්මස්වලට කුමක් සිදුවේද?", "වර්ණ වෙනසක් සිදු නොවේ", "තද රතු පැහැයට හැරේ", "තද කොළ පැහැයට හැරේ", "සුදු පැහැයට හැරේ", "නිර්ධ්‍රැවීය බෙන්සීන්වලදී HCl අයනීකරණය වී H⁺ අයන සාදන්නේ නැත."),
    q("කැල්සියම් කාබනේට් (CaCO₃) සහ කැල්සියම් හයිඩ්‍රොක්සයිඩ් (Ca(OH)₂) අතරින් ශක්තිමත්ව රත් කළ විට CaO හා CO₂ බවට වියෝජනය වන්නේ කුමක්ද?", "කැල්සියම් කාබනේට් (CaCO₃)", "කැල්සියම් හයිඩ්‍රොක්සයිඩ්", "දෙකම සෝඩියම් සාදයි", "කිසිවක් වියෝජනය නොවේ", "හුණු පෝරණුවලදී හුණුගල් පිළිස්සීම මෙම තාප වියෝජන ප්‍රතික්‍රියාවයි."),
    q("මූලද්‍රව්‍යයක් වන Na, Ca, Fe සහ Cu අතුරින් වඩාත් ස්ථායී නයිට්‍රේටයක් හා කාබනේටයක් සාදන්නේ කවරෙක්ද?", "සෝඩියම් (Na)", "කැල්සියම් (Ca)", "යකඩ (Fe)", "තඹ (Cu)", "සක්‍රියතා ශ්‍රේණියේ ඉහළම පිහිටි ලෝහවල සංයෝග ඉතා ස්ථායී බැවින් Na₂CO₃ බුන්සන් දැල්ලෙන් වියෝජනය නොවේ."),
    q("වීදුරුවක ඇති 0.1 mol NaOH සම්පූර්ණයෙන්ම උදාසීන කිරීමට අවශ්‍ය H₂SO₄ මවුල ප්‍රමාණය කීයද?", "0.05 mol", "0.1 mol", "0.2 mol", "0.4 mol", "2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O; NaOH : H₂SO₄ = 2 : 1 බැවින් 0.05 mol අවශ්‍ය වේ."),
    q("වීදුරුවක ඇති Cu(NO₃)₂ තදින් රත් කළ විට කළු CuO සමඟ පිටවන දුඹුරු පැහැති වායුව කුමක්ද?", "නයිට්‍රජන් ඩයොක්සයිඩ් (NO₂)", "ඔක්සිජන් පමණි", "හයිඩ්‍රජන්", "ක්ලෝරීන්", "2Cu(NO₃)₂ → 2CuO + 4NO₂(දුඹුරු) + O₂."),
    q("ලෝහ කැබලි 4 ක් පරීක්ෂා කිරීමේදී, X සිසිල් ජලය සමඟ ද, Y හුමාලය සමඟ පමණක් ද, Z අම්ල සමඟ පමණක් ද ප්‍රතික්‍රියා කරයි. W කිසිවක් සමඟ ප්‍රතික්‍රියා නොකරයි. සක්‍රියතාව අවරෝහණ පිළිවෙළ කුමක්ද?", "X > Y > Z > W", "W > Z > Y > X", "Y > X > Z > W", "Z > Y > X > W", "සිසිල් ජලය සමඟ ප්‍රතික්‍රියා කරන්නා වඩාත්ම සක්‍රීය වේ."),
    q("ලෝහ සක්‍රියතා ශ්‍රේණියේ සින්ක් (Zn) සහ ඊයම් (Pb) අතර පිහිටන ලෝහය කුමක්ද?", "යකඩ (Fe)", "සෝඩියම් (Na)", "තඹ (Cu)", "රිදී (Ag)", "Zn > Fe > Sn > Pb > Cu."),
    q("විද්‍යුත් විච්ඡේදන ක්‍රමයෙන් නිස්සාරණය කළ යුතුම, කාබන් මගින් ඔක්සිහරණය කළ නොහැකි ලෝහයක් වන්නේ කුමක්ද?", "ඇලුමිනියම් (Al) හෝ සෝඩියම් (Na)", "යකඩ (Fe)", "සින්ක් (Zn)", "ඊයම් (Pb)", "Al සහ ඊට ඉහළින් ඇති K, Na, Ca, Mg ලෝහ කාබන්ට වඩා ඔක්සිජන් කෙරෙහි ආකර්ෂණය වැඩිය."),
    q("දී ඇති රසායනික ප්‍රතික්‍රියාවක ක්ෂේත්‍ර උෂ්ණත්වය ඉහළ ගොස් තාපය පිටවේ නම් බන්ධන බිඳීමට වැය වූ ශක්තිය හා නව බන්ධන සෑදීමේදී පිටවූ ශක්තිය කෙබඳුද?", "බන්ධන සෑදීමේදී පිටවූ ශක්තිය බිඳීමට ගත් ශක්තියට වැඩිය", "බන්ධන බිඳීමට ගත් ශක්තිය පිටවූ ශක්තියට වඩා වැඩිය", "බන්ධන සෑදීමේ හා බිඳීමේ ශක්තීන් දෙකම සමාන වේ", "ප්‍රතික්‍රියාවේදී කිසිදු රසායනික බන්ධනයක් නොකැඩේ", "එබැවින් ශුද්ධ වශයෙන් තාපය පරිසරයට නිදහස් වේ."),
    q("බොහෝ විට පරීක්ෂණාගාරයේදී CO₂ වායුව රැස් කිරීම සඳහා භාවිත කරන ක්‍රමය කුමක්ද?", "වාතය ඉහළට විස්ථාපනය කිරීම (පහළට පිරවීම)", "වාතය පහළට විස්ථාපනය කිරීම", "උණු ජලය යට රැස් කිරීම", "ප්ලාස්ටික් පෙරීම", "CO₂ වාතයට වඩා බර (ඝනත්වය වැඩි) වායුවක් බැවින් වායු සරාවේ පතුලේ එකතු වේ."),
    q("හයිඩ්‍රජන් (H₂) හා ඇමෝනියා (NH₃) වායු රැස් කර ගැනීමේදී වායු සරාව මුනින් අතට (උඩුකුරු කර) අල්ලන්නේ ඇයි?", "වාතයට වඩා සැහැල්ලු බැවින් ඉහළට ගමන් කිරීම", "වාතයට වඩා බර බැවින් පහළට ගමන් කිරීම", "ඒවා ජලයේ කිසිසේත් දිය නොවන වායු වීම", "ඒවා ප්‍රබල ආම්ලික ගුණ පෙන්වන වායු වීම", "වාතය පහළට විස්ථාපනය කරමින් සැහැල්ලු වායු ඉහළ රැස් කෙරේ."),
    q("ලා කොළ පැහැති FeSO₄ ද්‍රාවණයක් වාතයට නිරාවරණය කර තැබූ විට එය ක්‍රමයෙන් කහ-දුඹුරු පැහැයට හැරෙන්නේ ඇයි?", "Fe²⁺ අයන වාතයේ ඔක්සිජන් මඟින් Fe³⁺ වීම", "ද්‍රාවණයෙන් තඹ ලෝහය පතුලේ තැන්පත් වීම", "ද්‍රාවණයේ ඇති ජලය සම්පූර්ණයෙන් වාෂ්ප වීම", "ද්‍රාවණයෙන් සල්ෆර් වායුවක් ලෙස පිටවීම", "Fe²⁺ (ලා කොළ) → Fe³⁺ (කහ-දුඹුරු)."),
    q("කිසියම් ලෝහ කාබනේටයක් රත් කළ විට වියෝජනය වී වර්ණ රහිත වායුවක් ද කහ පැහැ ඝන අවශේෂයක් ද (සිසිල් කළ විට සුදු) ලබා දේ. එම කාබනේටය කුමක්ද?", "සින්ක් කාබනේට් (ZnCO₃)", "කැල්සියම් කාබනේට්", "කොපර් කාබනේට්", "සෝඩියම් කාබනේට්", "ZnCO₃ → ZnO + CO₂; උණුසුම් ZnO කහ පැහැති වන අතර සිසිල් ZnO සුදු පැහැතිය."),
    q("කොළ පැහැති කොපර් කාබනේට් (CuCO₃) කුඩු පරීක්ෂණ නළයක දමා තදින් රත් කළ විට ඉතිරි වන කළු ඝන ද්‍රව්‍යය කුමක්ද?", "කොපර්(II) ඔක්සයිඩ් (CuO)", "තඹ ලෝහය", "කාබන් කුඩු", "කොපර් සල්ෆයිඩ්", "CuCO₃ (කොළ) → CuO (කළු) + CO₂."),
    q("ගල් අඟුරු බලාගාරවලින් පිටවන SO₂ වායුව උදාසීන කර වායු දූෂණය වැළැක්වීමට දුම්නලවල භාවිත කරන භාෂ්මික ද්‍රව්‍යය කුමක්ද?", "කැල්සියම් කාබනේට් හෝ හුණු", "සාන්ද්‍ර සල්ෆියුරික් අම්ලය", "ද්‍රවීකෘත මීතේන් වායුව", "ග්ලූකෝස් කාබනික සංයෝගය", "SO₂ + CaO → CaSO₃ (ෆ්ලූ ගෑස් ඩීසල්ෆරීකරණය)."),
    q("සෝඩියම් හයිඩ්‍රොක්සයිඩ් හා HCl අතර ප්‍රතික්‍රියාවේදී pH මීටරයක් තබා ඇත්නම්, අම්ලයට ක්‍රමයෙන් NaOH දමන විට pH අගය වෙනස් වන්නේ කෙසේද?", "1 සිට 7 හරහා 13 පමණ දක්වා ඉහළ යයි", "14 සිට 1 දක්වා පහළ බසී", "සැමවිටම 7 හි නියතව පවතී", "7 සිට 0 දක්වා අඩු වේ", "අන්ත ලක්ෂ්‍යය අසලදී pH අගයේ තියුණු වැඩිවීමක් දක්නට ලැබේ."),
    q("මවුලික ස්කන්ධය M වන වායුවක n මවුල ප්‍රමාණයක ස්කන්ධය m නම් එම රාශි අතර නිවැරදි සම්බන්ධය කුමක්ද?", "m = n × M", "n = m × M", "M = n / m", "n = M / m", "මවුල ගණන = ස්කන්ධය / මවුලික ස්කන්ධය (n = m / M)."),
    q("ඇවගාඩ්‍රෝ නියමයට (Avogadro's law) අනුව සමාන උෂ්ණත්වය හා පීඩනය යටතේ සමාන පරිමා ඇති ඕනෑම වායු දෙකක සමාන වන්නේ කුමක්ද?", "අණු සංඛ්‍යාව (මවුල සංඛ්‍යාව)", "මුළු ස්කන්ධය", "ඝනත්වය", "පරමාණුක ක්‍රමාංකය", "සම්මත උෂ්ණත්ව හා පීඩන (STP) යටතේ ඕනෑම වායුවක මවුල 1 ක පරිමාව 22.4 dm³ වේ."),
    q("කිසියම් රසායනික ප්‍රතික්‍රියාවකදී ලෝහයක් ඔක්සිජන් සමඟ සෘජුවම සංයෝජනය වීමට උදාහරණයක් වන්නේ කුමක්ද?", "4Na + O₂ → 2Na₂O", "CaCO₃ → CaO + CO₂", "Zn + CuSO₄ → ZnSO₄ + Cu", "NaOH + HCl → NaCl + H₂O", "මූලද්‍රව්‍ය දෙකක් එක් වී තනි සංයෝගයක් සෑදීම සංයෝජන ප්‍රතික්‍රියාවකි."),
    q("ජලයේ ඇති හයිඩ්‍රජන් පෙරොක්සයිඩ් බෝතලයක් විවෘත කර ඇඟිල්ලක තැවරූ විට සුදු පැහැති පෙන බුබුළු නැඟීමට හේතුව කුමක්ද?", "පටකවල එන්සයිම මඟින් H₂O₂ වියෝජනය වීම", "සමේ ඇති ලුණු සමඟ ක්ෂණිකව ප්‍රතික්‍රියා වීම", "සම මතුපිටින් H₂ වායුව වේගයෙන් සෑදීම", "සමේ සෛල සම්පූර්ණයෙන් දියවී යාම", "තුවාල පිරිසිදු කිරීමේදී පෙන නඟින්නේ ඔක්සිජන් බුබුළු පිටවීම නිසාය."),
    q("H₂SO₄ 2 mol තුළ අඩංගු ඔක්සිජන් පරමාණු මවුල සංඛ්‍යාව කීයද?", "8 mol", "4 mol", "2 mol", "6 mol", "H₂SO₄ 1 mol තුළ O පරමාණු 4 mol ඇත; 2 mol තුළ 2 × 4 = 8 mol වේ."),
    q("කිසියම් ද්‍රව්‍යයක 'ආනුභවික සූත්‍රය' (Empirical formula) CH₂O වන අතර එහි සාපේක්ෂ අණුක ස්කන්ධය 180 වේ නම් අණුක සූත්‍රය කුමක්ද? (CH₂O = 30)", "C₆H₁₂O₆", "C₂H₄O₂", "C₃H₆O₃", "CH₂O", "n = 180 / 30 = 6 -> (CH₂O)₆ = C₆H₁₂O₆."),
    q("සෝඩියම් ක්ලෝරයිඩ් විද්‍යුත් විච්ඡේදනයෙන් කාර්මිකව සෝඩියම් ලෝහය නිස්සාරණය කරන 'ඩවුන්ස් කෝෂයේ' CaCl₂ මිශ්‍ර කරන්නේ ඇයි?", "NaCl හි ඉහළ ද්‍රවාංකය පහත හෙළීමට", "කැල්සියම් ලෝහය වැඩිපුර නිපදවීමට", "ක්ලෝරීන් වායුව පිටවීම වැළැක්වීමට", "පද්ධතියට ජලය එක් කර තබා ගැනීමට", "ද්‍රවාංකය අඩු කිරීමෙන් විශාල තාප ශක්තියක් ඉතිරි වේ."),
    q("ලෝහ කිහිපයක සක්‍රීයතාව සැසඳීමේදී MgSO₄, ZnSO₄ සහ FeSO₄ ද්‍රාවණ කිසිවක් සමඟ ප්‍රතික්‍රියා නොකරන ලෝහය කුමක්ද?", "තඹ (Cu)", "මැග්නීසියම් (Mg)", "සින්ක් (Zn)", "යකඩ (Fe)", "තඹ සක්‍රීයතා ශ්‍රේණියේ ඉතා පහළින් පවතින බැවින් එම ලෝහ අයන විස්ථාපනය නොකරයි."),
    q("වීදුරු පාත්‍රයක ඇති රසායනික ප්‍රතික්‍රියාවකදී H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g) සිදු වේ නම් මෙය කුමන ප්‍රතික්‍රියාව නිරූපණය කරයිද?", "අම්ලයක් හා බයිකාබනේටයක් අතර අයනික සමීකරණය", "ලෝහයක් හා අම්ලයක් අතර ප්‍රතික්‍රියාව", "උදාසීනීකරණය පමණි", "විද්‍යුත් විච්ඡේදනය", "Na⁺ සහ Cl⁻ ප්‍රේක්ෂක අයන ඉවත් කළ විට මෙම ශුද්ධ අයනික සමීකරණය ලැබේ."),
    q("විද්‍යුත් ආලේපනය කිරීමට පෙර යකඩ වස්තුවක් තනුක අම්ලයක හා වැලි කඩදාසියකින් හොඳින් පිරිසිදු කරන්නේ ඇයි?", "මතුපිට මලකඩ ඉවත් කර ආලේපනය තදින් බැඳීමට", "ලෝහ වස්තුව අම්ලයේ සම්පූර්ණ දිය කිරීමට", "ලෝහ වස්තුවේ මුළු බර අඩකින් අඩු කිරීමට", "පරිපථයේ විදුලිය ක්ෂණිකව විසන්ධි කිරීමට", "පිරිසිදු නොකළහොත් ලෝහ ස්තරය පහසුවෙන් ගැලවී යයි."),
    q("CaCO₃(s) + 2HCl(aq) → CaCl₂(aq) + H₂O(l) + CO₂(g) ප්‍රතික්‍රියාවේදී නිපදවෙන වායු මවුල 0.5 ක් ලබා ගැනීමට ප්‍රතික්‍රියා කළ යුතු HCl මවුල ගණන කීයද?", "1.0 mol", "0.5 mol", "2.0 mol", "0.25 mol", "HCl : CO₂ අනුපාතය 2 : 1 බැවින් CO₂ 0.5 mol සඳහා HCl 1.0 mol අවශ්‍ය වේ."),
    q("කාබනික අම්ලයක් වන එතනොයික් අම්ලය (CH₃COOH) මැග්නීසියම් සමඟ ප්‍රතික්‍රියා කරන විට පිටවන වායුව කුමක්ද?", "හයිඩ්‍රජන් (H₂)", "කාබන් ඩයොක්සයිඩ්", "මීතේන්", "ඔක්සිජන්", "දුබල අම්ලයක් වුවද සක්‍රීය ලෝහ සමඟ සෙමෙන් H₂ පිට කරයි."),
    q("මූලද්‍රව්‍යයක් වන Na₂O, P₄O₁₀, SO₂ සහ CO₂ අතුරින් ජලයේ දිය වී නිල් ලිට්මස් රතු නොකරන (රතු ලිට්මස් නිල් කරන) ඔක්සයිඩය කුමක්ද?", "සෝඩියම් ඔක්සයිඩ් (Na₂O)", "පොස්පරස් පෙන්ටොක්සයිඩ්", "සල්ෆර් ඩයොක්සයිඩ්", "කාබන් ඩයොක්සයිඩ්", "Na₂O + H₂O → 2NaOH (ප්‍රබල ක්ෂාරයකි)."),
    q("පොටෑසියම් හා ජලය අතර ප්‍රතික්‍රියාව 2K + 2H₂O → 2KOH + H₂ ලෙස දැක්වේ. මෙහිදී H₂ මවුල 0.5 ක් නිපදවීමට අවශ්‍ය K ස්කන්ධය කීයද? (K = 39)", "39 g", "78 g", "19.5 g", "13 g", "K : H₂ = 2 : 1 බැවින් H₂ 0.5 mol සඳහා K මවුල 1.0 (39 g) අවශ්‍ය වේ."),
    q("ඇලුමිනියම් හයිඩ්‍රොක්සයිඩ් (Al(OH)₃) යනු ජලයේ දිය නොවන නමුත් අම්ල හා ප්‍රබල ක්ෂාර දෙකම සමඟ ප්‍රතික්‍රියා කරන භෂ්මයකි. එය හඳුන්වන්නේ කෙසේද?", "උභයගුණී හයිඩ්‍රොක්සයිඩයක් (Amphoteric)", "ප්‍රබල ක්ෂාරයක්", "ප්‍රබල අම්ලයක්", "උදාසීන ලවණයක්", "Zn(OH)₂ සහ Pb(OH)₂ ද උභයගුණී ගුණ පෙන්වයි."),
    q("වීදුරු පාත්‍රයක ඇති NH₄Cl හා Ca(OH)₂ මිශ්‍ර කර රත් කළ විට ඇමෝනියා වායුව ලැබේ. එම වායුව වියළීමට යොදා ගත යුතු වියළකාරකය කුමක්ද?", "පිළිස්සූ හුණු හෙවත් CaO", "සාන්ද්‍ර සල්ෆියුරික් අම්ලය", "සාන්ද්‍ර හයිඩ්‍රොක්ලෝරික් අම්ලය", "නිර්ජලීය කොපර් සල්ෆේට්", "ඇමෝනියා ක්ෂාරීය වායුවක් බැවින් ආම්ලික H₂SO₄ සමඟ ප්‍රතික්‍රියා කරයි; CaO භාෂ්මික බැවින් ප්‍රතික්‍රියා නොකරයි."),
    q("CO₂ වායුව වියළීම සඳහා සුදුසුම වියළකාරකය වන්නේ කුමක්ද?", "සාන්ද්‍ර සල්ෆියුරික් අම්ලය හෝ නිර්ජලීය CaCl₂", "සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH)", "කැල්සියම් ඔක්සයිඩ් (CaO)", "පොටෑසියම් හයිඩ්‍රොක්සයිඩ්", "CO₂ ආම්ලික වායුවක් බැවින් NaOH හෝ CaO භාවිත කළහොත් ඒ සමඟ ප්‍රතික්‍රියා කරයි."),
    q("සෝඩියම් සල්ෆේට් (Na₂SO₄, M = 142 g mol⁻¹) මවුල 0.5 ක අඩංගු ඔක්සිජන් පරමාණු මවුල ගණන කීයද?", "2.0 mol", "4.0 mol", "0.5 mol", "1.0 mol", "එක් Na₂SO₄ ඒකකයක O පරමාණු 4 ක් ඇති බැවින් 0.5 × 4 = 2.0 mol."),
    q("කැල්සියම් නයිට්‍රේට් (Ca(NO₃)₂) වල සාපේක්ෂ සූත්‍ර ස්කන්ධය කීයද? (Ca = 40, N = 14, O = 16)", "164", "102", "134", "148", "40 + 2 × (14 + 48) = 40 + 124 = 164."),
    q("රසායනික ප්‍රතික්‍රියාවකදී පීඩනය වැඩි කිරීමෙන් සීඝ්‍රතාවය සැලකිය යුතු ලෙස වැඩි වන්නේ කුමන ප්‍රතික්‍රියක අඩංගු අවස්ථාවලද?", "වායුමය ප්‍රතික්‍රියක (Gaseous reactants)", "ඝන ප්‍රතික්‍රියක පමණක්", "ජලීය ද්‍රාවණ පමණක්", "ද්‍රව ප්‍රතික්‍රියක පමණක්", "පීඩනය වැඩි කළ විට වායු අණු ළං වී ඒකක පරිමාවක සාන්ද්‍රණය හා ගැටුම් සංඛ්‍යාතය ඉහළ යයි."),
    q("Zn + 2HCl → ZnCl₂ + H₂ ප්‍රතික්‍රියාවේදී කොපර් සල්ෆේට් බිංදු කිහිපයක් දැමූ විට H₂ පිටවීම වේගවත් වන්නේ ඇයි?", "තඹ තැන්පත් වී විද්‍යුත් රසායනික කෝෂ සෑදීම", "අම්ලයේ සාන්ද්‍රණය ක්ෂණිකව දෙගුණ වීම", "තඹ මඟින් අමතර ජලය නිෂ්පාදනය කිරීම", "සින්ක් ලෝහය වේගයෙන් සිසිල් බවට පත්වීම", "මෙය ප්‍රායෝගික පරීක්ෂණාගාරයේදී සුලබව දැකිය හැකි සංසිද්ධියකි."),
    q("ලෝහ කිහිපයක ප්‍රතික්‍රියා අනුව Fe₂O₃ + 2Al → 2Fe + Al₂O₃ සිදුවේ. මෙහිදී වඩා සක්‍රීය ලෝහය හා ඔක්සිකාරකය පිළිවෙළින් කවුද?", "Al වඩා සක්‍රීයයි; Fe₂O₃ ඔක්සිකාරකයයි", "Fe වඩා සක්‍රීයයි; Al ඔක්සිකාරකයයි", "Al₂O₃ ඔක්සිකාරකයයි", "Al ඔක්සිකාරකයයි", "Al ඉලෙක්ට්‍රෝන දී Fe³⁺ ඔක්සිහරණය කරයි."),
    q("සෝඩියම් ක්ලෝරයිඩ් ජලීය ද්‍රාවණයක් විද්‍යුත් විච්ඡේදනය කිරීමේදී ඇනෝඩයේදී නිදහස් වන කොළ-කහ පැහැති වායුව කුමක්ද?", "ක්ලෝරීන් (Cl₂)", "හයිඩ්‍රජන් (H₂)", "ඔක්සිජන් (O₂)", "නයිට්‍රජන් (N₂)", "සාන්ද්‍ර NaCl ද්‍රාවණයේදී Cl⁻ අයන ඔක්සිකරණය වී Cl₂ පිටවන අතර ද්‍රාවණය NaOH බවට පත් වේ."),
    q("වීදුරු පාත්‍රයක ඇති කොපර්(II) සල්ෆේට් ද්‍රාවණයක් කාබන් ඉලෙක්ට්‍රෝඩ මගින් විද්‍යුත් විච්ඡේදනය කළ විට කැතෝඩයේදී දිස්වන්නේ කුමක්ද?", "රතු-දුඹුරු පැහැති තඹ ලෝහ ස්තරයක් තැන්පත් වීම", "හයිඩ්‍රජන් බුබුළු", "ඔක්සිජන් බුබුළු", "සුදු අවක්ෂේපයක්", "Cu²⁺ අයන H⁺ වලට වඩා පහසුවෙන් කැතෝඩයේදී ඔක්සිහරණය වේ."),
    q("ලුණු ද්‍රාවණයක pH අගය 7 ට වඩා වැඩි (ක්ෂාරීය) වන්නේ පහත සඳහන් කුමන ලවණය ජලයේ දිය කළ විටද?", "සෝඩියම් කාබනේට් (Na₂CO₃)", "සෝඩියම් ක්ලෝරයිඩ් (NaCl)", "පොටෑසියම් නයිට්‍රේට් (KNO₃)", "ඇමෝනියම් ක්ලෝරයිඩ් (NH₄Cl)", "Na₂CO₃ සෑදෙන්නේ ප්‍රබල භෂ්මයකින් (NaOH) හා දුබල අම්ලයකිනි (H₂CO₃)."),
    q("තනුක H₂SO₄ අම්ලය සහ සින්ක් කාබනේට් (ZnCO₃) ප්‍රතික්‍රියා කළ විට සෑදෙන ලවණය කුමක්ද?", "සින්ක් සල්ෆේට් (ZnSO₄)", "සින්ක් ක්ලෝරයිඩ්", "සින්ක් හයිඩ්‍රොක්සයිඩ්", "සින්ක් නයිට්‍රේට්", "ZnCO₃ + H₂SO₄ → ZnSO₄ + H₂O + CO₂."),
    q("කිසියම් සංයෝගයක රසායනික ප්‍රතික්‍රියාවකදී පරමාණුවක ඔක්සිකරණ අංකය (Oxidation state) +2 සිට +3 දක්වා වැඩි වූයේ නම් එයට සිදු වී ඇත්තේ කුමක්ද?", "ඉලෙක්ට්‍රෝන පිට කරන ඔක්සිකරණය", "ඉලෙක්ට්‍රෝන ලබාගන්නා ඔක්සිහරණය", "අම්ල භෂ්ම උදාසීනීකරණ ක්‍රියාව", "ජල අණු එක්වන ජලවිච්ඡේදන ක්‍රියාව", "Fe²⁺ → Fe³⁺ + e⁻."),
    q("මැග්නීසියම් 1 mol ක් සහ ඔක්සිජන් (O₂) 1 mol ක් සංවෘත භාජනයක ප්‍රතික්‍රියා කළ විට ප්‍රතික්‍රියාවෙන් පසු ඉතිරි වන අතිරික්ත ප්‍රතික්‍රියකය කුමක්ද? (2Mg + O₂ → 2MgO)", "ඔක්සිජන් 0.5 mol ක් ඉතිරි වේ", "මැග්නීසියම් 0.5 mol ක් ඉතිරි වේ", "කිසිවක් ඉතිරි නොවේ", "MgO 2 mol සෑදේ", "Mg 1 mol සම්පූර්ණයෙන් දැවීමට අවශ්‍ය වන්නේ O₂ 0.5 mol පමණි (සීමාකාරී ප්‍රතික්‍රියකය Mg)."),
    q("විදුලි පන්දමක ඇති සාමාන්‍ය කාබන්-සින්ක් වියළි කෝෂයක විධ්‍රැවීකරණය (Polarization - H₂ වායු බුබුළු බැඳීම) වැළැක්වීමට භාවිත කරන ද්‍රව්‍යය කුමක්ද?", "මැන්ගනීස් ඩයොක්සයිඩ් (MnO₂)", "කාබන් කුඩු පමණක්", "සින්ක් කුඩු", "ජලය", "MnO₂ හයිඩ්‍රජන් ඔක්සිකරණය කර ජලය බවට පත් කරමින් විද්‍යුත් ගාමක බලය නියතව තබයි."),
    q("කාර්මිකව සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH) සහ ක්ලෝරීන් (Cl₂) එකවර නිපදවන ක්ලෝර්-ඇල්කලි කර්මාන්තයේදී අමුද්‍රව්‍යය ලෙස ගන්නේ කුමක්ද?", "සාන්ද්‍ර NaCl ලවණ ද්‍රාවණය (බ්‍රයින්)", "ස්වාභාවික හුණුගල් නිධි (CaCO₃)", "මැග්නීසියම් ඔක්සයිඩ් (MgO) කුඩු", "ද්‍රව ඇමෝනියා (NH₃) ද්‍රාවණය", "2NaCl(aq) + 2H₂O(l) → 2NaOH(aq) + Cl₂(g) + H₂(g)."),
    q("දී ඇති රසායනික ප්‍රතික්‍රියා අතුරින් 'වියෝජන ප්‍රතික්‍රියාවක්' වන්නේ කුමක්ද?", "2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂", "2H₂ + O₂ → 2H₂O", "Fe + CuSO₄ → FeSO₄ + Cu", "HCl + NaOH → NaCl + H₂O", "තනි සංයෝගයක් තාපය මගින් සරල ඵල කිහිපයකට බිඳී යාම වියෝජනයකි."),
    q("ප්‍රතික්‍රියා ශක්ති මට්ටම් සටහනක ප්‍රතික්‍රියකවල ශක්ති මට්ටමේ සිට සංක්‍රාන්ති අවස්ථාවේ (උපරිමයේ) මුදුන දක්වා ඇති අවම ශක්ති වෙනස කුමක්ද?", "ප්‍රතික්‍රියාවේ සක්‍රීයන ශක්තිය", "ප්‍රතික්‍රියාවේ එන්තැල්පි විපර්යාසය", "පරමාණුවක අයනීකරණ ශක්තිය", "ද්‍රව්‍යයේ විශිෂ්ට ගුප්ත තාපය", "ප්‍රතික්‍රියාව ආරම්භ වීමට ප්‍රතික්‍රියක අණු සතුව අවම වශයෙන් Eₐ ශක්තිය තිබිය යුතුය.")
  )
}
